export const getLessonBatch = (moduleIdOrLessonId: string): UniversalLessonUnit[] => {
  // Check if it's a full module request
  const module = COURSE_MAP.find(m => m.id === moduleIdOrLessonId);
  if (module) {
    return ALL_LESSONS.filter(l => module.lessonIds.includes(l.id));
  }

  // Check if it's a specific lesson request (return that lesson wrapped in array)
  return ALL_LESSONS.filter(l => l.id === moduleIdOrLessonId);
};

